/**
 * Client-side mirror of the backend quiz seed (backend/app/data/quiz_bank.py).
 * It backs the service boundary when the API is unavailable and supplies the
 * answer key used for post-submission feedback. The content must stay in sync
 * with the backend seed file.
 */
export interface SeedQuizQuestion {
  question: string;
  options: [string, string, string, string];
  correct_answer: AnswerLetter;
  explanation: string;
  category?: QuizCategory;
}

